import * as React from 'react';
import { Box, Typography, Button, TextField, List, ListItem, ListItemText, IconButton, Alert } from '@mui/material';
import { Add, Delete } from '@mui/icons-material';
import axios from 'axios';
import { useAuth } from '../context/AuthContext.tsx';

interface ShortenLink {
  id: number;
  original_url: string;
  short_code: string;
  created_at: string;
}

export default function Dashboard() {
  const { token, logout } = useAuth();
  const [links, setLinks] = React.useState<ShortenLink[]>([]);
  const [originalUrl, setOriginalUrl] = React.useState('');
  const [error, setError] = React.useState('');

  const fetchLinks = React.useCallback(async () => {
    try {
      const response = await axios.get('/api/v1/shorten-links/', {
        headers: { Authorization: `Token ${token}` },
      });
      setLinks(response.data.data);
      setError('');
    } catch (err: any) {
      setError('Failed to fetch links.');
      console.error(err);
    }
  }, [token]);

  React.useEffect(() => {
    fetchLinks();
  }, [fetchLinks]);

  const handleCreate = async () => {
    try {
      await axios.post(
        '/api/v1/shorten-links',
        { original_url: originalUrl },
        {
          headers: { Authorization: `Token ${token}` },
        }
      );
      setOriginalUrl('');
      fetchLinks();
    } catch (err: any) {
      setError('Failed to create link.');
      console.error(err);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      await axios.delete(`/api/v1/shorten-links/${id}`, {
        headers: { Authorization: `Token ${token}` },
      });
      fetchLinks();
    } catch (err: any) {
      setError('Failed to delete link.');
      console.error(err);
    }
  };

  return (
    <Box sx={{ p: 4 }}>
      <Typography variant="h4" gutterBottom>
        Dashboard
      </Typography>

      <Typography variant="body1" sx={{ mb: 3 }}>
        Welcome! Manage your shorten links here.
      </Typography>

      <Box sx={{ mb: 3 }}>
        <TextField label="Original URL" value={originalUrl} onChange={(e) => setOriginalUrl(e.target.value)} fullWidth sx={{ mb: 2 }} />
        <Button variant="contained" startIcon={<Add />} onClick={handleCreate}>
          Create Shorten Link
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Typography variant="h6" gutterBottom>
        Your Shorten Links
      </Typography>
      <List>
        {links.map((link) => (
          <ListItem
            key={link.id}
            secondaryAction={
              <IconButton onClick={() => handleDelete(link.id)}>
                <Delete />
              </IconButton>
            }
          >
            <ListItemText primary={link.original_url} secondary={`Short: http://localhost:8080/r/${link.short_code}`} />
          </ListItem>
        ))}
      </List>

      <Button variant="contained" color="error" onClick={logout} sx={{ mt: 3 }}>
        Logout
      </Button>
    </Box>
  );
}
